/**
 * The standard emoji, by Unicode's groups, with their official names and
 * their Discord-style shortcodes: what every emoji picker offers beside
 * Kryoto's own (components/rich-editor.tsx and the status picker on kryo.to,
 * src/rich/RichEditor.tsx in Kryoto Desktop and Kryoto Mobile). They are
 * drawn by the reader's own emoji font.
 *
 * Generated by scripts/build-emoji-catalog.mjs from Unicode's emoji-test.txt
 * (1870 emoji up to Emoji 15.0, no skin-tone variants) and gemoji's
 * shortcodes (lib/emoji-shortcodes.ts). Do not edit by hand.
 *
 * Pure and dependency-free, and copied into Kryoto Desktop and Kryoto Mobile
 * (`pnpm sync:rich-text`). Pickers import it the first time they open.
 */

export type StandardEmoji = {
  char: string
  /** Unicode's name, lower case: "grinning face". */
  name: string
  /** Shortcodes without colons, the one to show first: ['joy']. */
  codes: string[]
  /** Unicode's subgroup ("face smiling"), searched but not shown. */
  sub: string
}

export const STANDARD_GROUPS = [
  { id: 'smileys', label: 'Smileys' },
  { id: 'people', label: 'People' },
  { id: 'nature', label: 'Nature' },
  { id: 'food', label: 'Food' },
  { id: 'activity', label: 'Activity' },
  { id: 'travel', label: 'Travel' },
  { id: 'objects', label: 'Objects' },
  { id: 'symbols', label: 'Symbols' },
  { id: 'flags', label: 'Flags' },
] as const

export type StandardGroupId = (typeof STANDARD_GROUPS)[number]['id']

