let parsed: { id: StandardGroupId; label: string; emoji: StandardEmoji[] }[] | null = null
let shown: { id: StandardGroupId; label: string; emoji: StandardEmoji[] }[] | null = null
let byChar: Map<string, StandardEmoji> | null = null

/** Every group with every emoji listed, drawable here or not. */
function allGroups(): { id: StandardGroupId; label: string; emoji: StandardEmoji[] }[] {
  if (parsed) return parsed
  const out: { id: StandardGroupId; label: string; emoji: StandardEmoji[] }[] = []
  let sub = ''
  for (const line of TABLE.split('\n')) {
    if (line.startsWith('@')) {
      const group = STANDARD_GROUPS.find((g) => g.id === line.slice(1))!
      out.push({ id: group.id, label: group.label, emoji: [] })
    } else if (line.startsWith('#')) sub = line.slice(1)
    else {
      const at = line.indexOf(' ')
      const bar = line.indexOf('|', at)
      const codes = line.slice(bar + 1)
      out[out.length - 1]!.emoji.push({ char: line.slice(0, at), name: line.slice(at + 1, bar), codes: codes ? codes.split(' ') : [], sub })
    }
  }
  parsed = out
  return out
}

let flagsDrawn: boolean | null = null

/**
 * Does this device's emoji font draw country and subdivision flags? Windows
 * draws none: 🇳🇱 comes out as the letters "NL". Where it cannot, the pickers
 * leave those flags out (a flag somebody else wrote still shows as their
 * letters, as everywhere on that device). Read once, from a canvas; true
 * without one.
 */
export function drawsFlags(): boolean {
  if (flagsDrawn !== null) return flagsDrawn
  flagsDrawn = true
  try {
    if (typeof document === 'undefined') return flagsDrawn
    const canvas = document.createElement('canvas')
    canvas.width = 20
    canvas.height = 20
    const ctx = canvas.getContext('2d', { willReadFrequently: true })
    if (!ctx) return flagsDrawn
    ctx.font = '16px "Apple Color Emoji", "Segoe UI Emoji", "Noto Color Emoji", "Twemoji Mozilla", emoji, sans-serif'
    ctx.textBaseline = 'top'
    ctx.fillStyle = '#000'
    ctx.fillText('🇳🇱', 0, 0)
    const px = ctx.getImageData(0, 0, 20, 20).data
    let colour = false
    for (let i = 0; i < px.length && !colour; i += 4) {
      colour = px[i + 3]! > 0 && (Math.abs(px[i]! - px[i + 2]!) > 60 || Math.abs(px[i + 1]! - px[i + 2]!) > 60)
    }
    flagsDrawn = colour
  } catch {
    // No canvas to ask: offer them.
  }
  return flagsDrawn
}

/** Can this device draw it? Only flags can be missing (drawsFlags). */
function drawable(e: StandardEmoji): boolean {
  return (e.sub !== 'country flag' && e.sub !== 'subdivision flag') || drawsFlags()
}

/** Every group with its emoji, in the pickers' order, without what this device cannot draw. */
export function standardGroups(): { id: StandardGroupId; label: string; emoji: StandardEmoji[] }[] {
  if (shown) return shown
  shown = allGroups().map((g) => ({ ...g, emoji: g.emoji.filter(drawable) }))
  return shown
}

const bare = (s: string) => s.replace(/️/g, '')

/** The entry for an emoji, with or without its variation selector; null for one not listed (a toned one). */
export function standardFor(char: string): StandardEmoji | null {
  if (!byChar) {
    byChar = new Map()
    for (const g of allGroups()) for (const e of g.emoji) byChar.set(bare(e.char), e)
  }
  return byChar.get(bare(char)) ?? null
}

/**
 * Emoji whose name, shortcodes or subgroup have every word of the query:
 * an exact name or shortcode first, then those that start with it, then the
 * rest. ":joy:" and "thumbs up" both work.
 */
export function searchStandard(query: string, limit = 160): StandardEmoji[] {
  const q = query.toLowerCase().replace(/:/g, ' ').trim()
  if (!q) return []
  const words = q.split(/[\s_]+/).filter(Boolean)
  const code = words.join('_')
  const tiers: StandardEmoji[][] = [[], [], []]
  for (const g of standardGroups()) {
    for (const e of g.emoji) {
      const hay = e.name + ' ' + e.codes.join(' ').replace(/_/g, ' ') + ' ' + e.sub
      if (!words.every((w) => hay.includes(w))) continue
      const tier = e.name === words.join(' ') || e.codes.includes(code) ? 0 : e.name.startsWith(words[0]!) || e.codes.some((c) => c.startsWith(code)) ? 1 : 2
      tiers[tier]!.push(e)
    }
  }
  return tiers.flat().slice(0, limit)
}
